CREATE TABLE IF NOT EXISTS registros (coleccion TEXT NOT NULL, id TEXT NOT NULL, data TEXT NOT NULL, actualizado INTEGER NOT NULL, PRIMARY KEY (coleccion, id));
CREATE TABLE IF NOT EXISTS fotos_blob (id TEXT PRIMARY KEY, mime TEXT NOT NULL, data BLOB NOT NULL, creado INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS suscripciones (endpoint TEXT PRIMARY KEY, p256dh TEXT NOT NULL, auth TEXT NOT NULL, creado INTEGER NOT NULL);
